export const harm = "<figure class=\"research-figure\" aria-labelledby=\"kl-harm-title\"><figcaption id=\"kl-harm-title\"><span class=\"figure-number\">02 / What the quantized model wrote instead of the original\u2019s choice</span><strong>Swaps to a near runner-up cost far more accuracy than swaps to far-out tokens.</strong></figcaption><div class=\"test-chart\"><div><b>an alternative the original also finds plausible</b><span class=\"bar-track base\"><span style=\"width:4%\"></span></span><em>0.5%</em></div><div><b>a rare token far down its list</b><span class=\"bar-track base\"><span style=\"width:11%\"></span></span><em>1.6%</em></div><div><b>a rare token ranked 6th\u201316th</b><span class=\"bar-track good\"><span style=\"width:42%\"></span></span><em>5.9%</em></div><div><b>a rare token ranked 2nd\u20135th</b><span class=\"bar-track bad\"><span style=\"width:88%\"></span></span><em>12.3%</em></div></div><p class=\"figure-foot\">How often each kind of swap turns a correct answer into a wrong one, measured by letting the original model finish the solution both ways (about 1,500 swaps from four quantized models; net rate, so swaps that happened to fix a wrong answer count against it). \u201cRare\u201d means the original gives the token under 1 in 1,000; \u201cranked\u201d is its position in the original\u2019s own list of candidates.</p></figure>";
